# Stored prices without a date come from the product dump of about this month;
# dating them today would make them look freshly checked.
UNKNOWN_PRICE_DATE = datetime.date(2026, 3, 1)


def move_prices_to_history(apps, schema_editor) -> None:
    """Existing prices become general starting prices, without a camp."""
    Ingredient = apps.get_model("recipes", "Ingredient")
    IngredientPrice = apps.get_model("recipes", "IngredientPrice")
    IngredientPrice.objects.bulk_create(
        IngredientPrice(
            ingredient=ingredient,
            price=ingredient.price_per_unit,
            unit=ingredient.unit,
            source="import",
            date=(
                django.utils.timezone.localdate(ingredient.price_updated)
                if ingredient.price_updated
                else UNKNOWN_PRICE_DATE
            ),
        )
        for ingredient in Ingredient.objects.exclude(price_per_unit=None)
    )


def restore_latest_prices(apps, schema_editor) -> None:
    Ingredient = apps.get_model("recipes", "Ingredient")
    IngredientPrice = apps.get_model("recipes", "IngredientPrice")
    for ingredient in Ingredient.objects.all():
        latest = (
            IngredientPrice.objects.filter(ingredient=ingredient, unit=ingredient.unit)
            .order_by("-date", "-pk")
            .first()
        )
        if latest:
            ingredient.price_per_unit = latest.price
            ingredient.save(update_fields=["price_per_unit"])


